let area='forest',form='human',pos=new THREE.Vector3(0,0,18),yaw=0,jump=0,vy=0,nearest=null,modalOpen=false,started=false,t=0,lastInterior='school';avatar.position.copy(pos);camera.position.set(0,12,33);camera.lookAt(0,0,12);
const held=new Set();let previousFocus=null;function show(html){held.clear();modalOpen=true;previousFocus=document.activeElement;$('card').innerHTML=html;$('modal').hidden=false;$('card').querySelector('button')?.focus()}
