function panel(tag,title,text,buttons=[]){if(progress.character?.preset==='Custom')text=text.replaceAll('Sierra','Windwalker');show(`<small>${tag}</small><h2>${title}</h2><p>${text}</p><div class="choices">${buttons.map((b,i)=>`<button class="choice" data-choice="${i}"><b>${b.title}</b>${b.sub?`<small>${b.sub}</small>`:''}</button>`).join('')}</div><button class="primary" id="closeDialog">Back to adventure →</button>`);$('closeDialog').onclick=close;buttons.forEach((b,i)=>$('card').querySelector(`[data-choice="${i}"]`).onclick=b.fn)}
let toastTime=0;function toast(text){$('toast').textContent=text;$('toast').style.opacity=1;toastTime=4}
function setForm(f){stable?.stop();if(recreation?.mode)recreation.stop();if(area==='drive')return;if((area==='city'||area==='store')&&!cityTrip.transformationAllowed(f))return;standUp();form=f;humanBody.visible=f==='human';wolfBody.visible=f==='wolf';birdBody.visible=f==='bird';document.querySelectorAll('[data-form]').forEach(b=>{b.classList.toggle('selected',b.dataset.form===f);b.setAttribute('aria-pressed',String(b.dataset.form===f))});$('jumpBtn').textContent=f==='bird'?'Flap ↑':'Jump ↑'}setForm('human');
function enter(where){if(village)village.root.visible=false;treeHouse.root.visible=false;recreation?.stop();cityTrip.hide();standUp();classroom.visible=false;area=where;outside.visible=where==='forest';inside.visible=where==='school';hutInside.visible=where==='hut';pos.set(0,0,where==='forest'?(lastInterior==='hut'?12:-18):where==='school'?7:9);if(where==='forest'&&lastInterior==='hut')pos.x=-24;if(where!=='forest')lastInterior=where;if(where==='hut')custom.hutLayout.gather();setForm('human');jump=vy=0;yaw=0;nearest=null;camera.position.set(pos.x,12,pos.z+16);$('location').textContent=where==='school'?'Redcliff High · Learning Hall':where==='hut'?'Your Class Hut · '+'Gemeinschaftsraum':'Redcliff · Whispering Forest';toast(where==='school'?'Welcome to Redcliff High. Walk to a desk to choose a subject.':where==='hut'?'Your shared hut. Talk, relax, or decorate.':'Back beneath the trees.');updateQuest()}
function updateQuest(){if(area==='store'){$('questChapter').textContent='SAN FRANCISCO · BAY BASKET';$('questTitle').textContent='Shop without revealing your secret';$('questText').textContent='Browse shelves, collect food and drinks, then pay at checkout with game coins. Leave through the exit to return to the city.';return}if(area==='city'||area==='drive'){$('questChapter').textContent='CITY TRIP · SAN FRANCISCO';$('questTitle').textContent=area==='drive'?'Take the coastal road':'Explore the crowded city';$('questText').textContent=area==='drive'?'Hold Up to drive, Down to brake, and Left or Right to steer. Arrive by car before walking through the city.':'Keep your Windwalker identity secret. Change forms only out of sight, inside a private booth. Explore on foot. Return to your parked car to drive back to Redcliff.';return}if(progress.learning.stage>0&&progress.learning.stage<6){$('questChapter').textContent='CHAPTER TWO · THE SILENT STREAM';$('questTitle').textContent='Follow the stream evidence';$('questText').textContent=['Observe the stream.','Plan and run a fair sample comparison.','Calculate the water flow.','Translate the Latin maintenance record.','Listen to Camille’s French account.','Connect the clues and explain your conclusion.'][progress.learning.stage]+' Open your Notebook to continue.';return}if(progress.learning.stage===6){$('questChapter').textContent='STREAM INVESTIGATOR · CASE COMPLETE';$('questTitle').textContent='A recovery plan for the stream';$('questText').textContent='Revisit your evidence, try the greenhouse challenge, or practise four subjects in your Notebook. The school mystery remains open.';return}$('questChapter').textContent='CHAPTER ONE · THE HIDDEN THREAT';let title,text;if(progress.savedSchool){title='Redcliff is safe… for now';text='Chapter one complete. Keep learning, visit friends, and make your hut your own.'}else if(!progress.met){title='Welcome to Redcliff';text='Follow the path to school. Meet Headmistress Rowan in the entrance hall.'}else if(progress.clues.length<3){title='Someone is hiding a secret';text=`Find clues (${progress.clues.length}/3): a forest satchel, the school archive, and a torn note in the hall.`}else if(progress.lessons.length<3){title='Knowledge protects the school';text=`Complete each subject (${progress.lessons.length}/3) to learn how to repair the school ward.`}else{title='Restore the school ward';text=progress.authorized?'Repair the blue crystal outside school using Rowan’s restoration charm.':'Bring your evidence to Headmistress Rowan. Then repair the blue crystal outside school.'}$('questTitle').textContent=title;$('questText').textContent=text}
const clueTexts={satchel:['The lost satchel','Behind a tree, you find a visitor’s satchel. Inside: a sketch of the school ward, with its weak point circled. Whoever owns this planned to break the school’s protective magic.'],ledger:['The archive ledger','The visitor register has a page torn out. A grey thread is trapped in the spine. The last entry reads: “North gate inspection — after sunset.” Someone has been using a false identity.'],note:['The torn note','A scrap beneath the noticeboard reads: “When the ward goes dark, Redcliff will fall. Leave before the moon rises.” A small silver feather is stamped on the corner. Who sent it?']};
function clue(id){if(!progress.met)return panel('A MYSTERY AWAITS','Something feels strange…','Talk to Headmistress Rowan first. She may know why these unusual objects matter.');const fresh=!progress.clues.includes(id);if(fresh){progress.clues.push(id);save();updateQuest()}panel(fresh?'NEW EVIDENCE · '+progress.clues.length+'/3':'JOURNAL EVIDENCE',clueTexts[id][0],clueTexts[id][1])}
function talk(who){if(who==='rowan'){if(!progress.met){progress.met=true;save();updateQuest();panel('HEADMISTRESS ROWAN','Welcome, Sierra. We need you.','Someone inside Redcliff is pretending to be a friend. They want to destroy our school by breaking its protective ward. Explore with your classmates, collect three clues, and study all three subjects. We will protect Redcliff together.')}else if(progress.clues.length===3&&progress.lessons.length===3&&!progress.authorized){progress.authorized=true;save();updateQuest();panel('THE EVIDENCE FITS','The silver feather…','“This is the mark of the Ashwing Circle,” Rowan whispers. “Someone entered using a false name. We still don’t know who. I will safeguard the pupils. Take this restoration charm to the blue ward crystal outside. Your three lessons will show you how to mend it.”')}else panel('HEADMISTRESS ROWAN',progress.savedSchool?'You protected Redcliff.':'Every clue matters.',progress.savedSchool?'The ward shines again, thanks to you and your classmates. The stranger fled before we could see their face. Keep your journal close — the silver feather mystery has only just begun.':`You have ${progress.clues.length} of 3 clues and completed ${progress.lessons.length} of 3 subjects. Look for the satchel east of the path, search the archive, and read the torn note. Come back when you are ready.`);return}
const dialogues={mira:['Mira','You made it! Our class huts are west of the main path. You can choose the walls, roof, and garden. I saw someone in a grey coat near the school archive. Their shoes were covered in forest mud.'],theo:['Theo','I was studying bird tracks when I found a strange satchel east of here. It is by a small clearing. Use wolf form to run faster, or blue jay form and tap Flap to fly above the trees.'],jun:['Jun','I love the hut garden! Lanterns would look beautiful. Yesterday I heard someone whisper “after sunset” by the noticeboard inside school. Rowan should hear about that.']};const d=dialogues[who]||dialogues.mira;panel('CLASSMATE · '+(area==='hut'?'YOUR HUT':'FOREST'),d[0],d[1],[{title:'Share what you found',sub:'Compare clues with your classmate',fn:()=>panel('WORKING TOGETHER',d[0]+' listens closely',progress.clues.length?'“A false name, a silver feather, and the ward… We should show Rowan the evidence. Let’s keep everyone safe and stay together.”':'“Let’s start with Headmistress Rowan. She always knows where to begin.”')}])}
const lessons={Mathematics:{intro:'A ward has three crystal rings. Learn to balance their energy with multiplication, division, and the order of operations.',qs:[['There are 6 trees in each of 7 rows. How many trees?',['36','42','48'],1,'6 × 7 = 42. Equal groups can be counted with multiplication.'],['Share 144 crystals equally among 12 pupils.',['12 each','14 each','16 each'],0,'144 ÷ 12 = 12, because 12 × 12 = 144.'],['What is 8 + 3 × 4?',['44','24','20'],2,'Multiply first: 3 × 4 = 12. Then 8 + 12 = 20.']]},'Forest Science':{intro:'Healthy forests and magical wards depend on balance. Study sunlight, ecosystems, and the water cycle.',qs:[['What do green plants use sunlight to make?',['Food (sugars)','Soil','Stones'],0,'Photosynthesis uses light energy to turn water and carbon dioxide into sugars; oxygen is released.'],['Why do decomposers matter in a forest?',['They stop rain','They return nutrients to soil','They make sunlight'],1,'Fungi and other decomposers break down dead material and recycle its nutrients.'],['Water vapour cools into tiny droplets. This is…',['Evaporation','Melting','Condensation'],2,'Condensation turns water vapour into liquid droplets, including the droplets in clouds.']]},Languages:{intro:'Words build trust. Practise simple French greetings and useful vocabulary with your classmates.',qs:[['How do you greet a classmate in French?',['Bonjour !','Merci !','Au revoir !'],0,'Bonjour means hello or good day.'],['What does “Nous sommes amis” mean?',['We are friends','We are teachers','We are tired'],0,'Nous = we; sommes = are; amis = friends.'],['How do you say “the school” in French?',['La forêt','La maison','L’école'],2,'L’école means the school. La forêt is the forest; la maison is the house.']]}};
let currentLesson=null,qIndex=0;function lessonMenu(name){return learning.subjectMenu(name==='Forest Science'?'Science':name==='Languages'?'French':name)}
function legacyLessonMenu(name){panel('REDCLIFF LEARNING HALL',name,lessons[name].intro,[{title:progress.lessons.includes(name)?'Practise again':'Begin lesson',sub:'3 questions · explanations · earn a subject badge',fn:()=>{currentLesson=name;qIndex=0;question()}}])}
function question(){const lesson=lessons[currentLesson],q=lesson.qs[qIndex];show(`<small>${currentLesson.toUpperCase()} · ${qIndex+1} / ${lesson.qs.length}</small><h2>${q[0]}</h2><div class="choices">${q[1].map((a,i)=>`<button class="choice" data-answer="${i}">${a}</button>`).join('')}</div><p id="lessonFeedback" aria-live="polite"></p><button class="close" id="leaveLesson">Leave lesson</button>`);$('leaveLesson').onclick=close;$('card').querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(Number(b.dataset.answer)!==q[2]){$('lessonFeedback').textContent='Almost! Think it through and try another answer.';b.disabled=true;b.style.opacity='.5';return}$('card').querySelectorAll('[data-answer]').forEach(a=>a.disabled=true);$('lessonFeedback').textContent='Correct! '+q[3];const next=document.createElement('button');next.className='primary';next.textContent=qIndex<lesson.qs.length-1?'Next question →':'Collect subject badge ✦';next.onclick=()=>{if(++qIndex<lesson.qs.length)question();else{if(!progress.lessons.includes(currentLesson))progress.lessons.push(currentLesson);save();updateQuest();panel('SUBJECT COMPLETE ✦',currentLesson+' badge earned','You learned something new — and strengthened the knowledge needed to restore the school ward. You can return to any desk to practise again.')}};$('lessonFeedback').after(next);next.focus()})}
function decorate(){panel('YOUR CLASS HUT','Make it your own.','Arrange your furniture or choose your hut exterior and roommate.',[{title:'Arrange furniture & study books',fn:()=>custom.roomEditor()},{title:'Walls, roof, garden & roommate',fn:exteriorDecorate}])}
function exteriorDecorate(){show(`<small>YOUR CLASS HUT</small><h2>A little home in the forest.</h2><p>Choose a look and a hut mate. Your choices are saved on this device.</p>${[['theme','Walls',[['fern','🌿 Fern'],['rose','🌸 Rose'],['sky','☁ Sky']]],['roof','Roof',[['cone','Classic'],['tall','Tall spire'],['flat','Low roof']]],['decor','Garden',[['flowers','🌷 Flowers'],['lanterns','🏮 Lanterns'],['shrubs','🌳 Shrubs'],...(progress.learning.stage===6?[['stones','◌ River stones']]:[])]],['roommate','Share your hut with',[['Mira','Mira'],['Theo','Theo'],['Jun','Jun']]]].map(([key,title,opts])=>`<h4>${title}</h4><div class="swatches">${opts.map(([id,n])=>`<button data-style="${key}" data-value="${id}" class="${progress[key]===id?'picked':''}">${n}</button>`).join('')}</div>`).join('')}<p>Hut mates are story characters in this single-player adventure.</p><button class="primary" id="finishDecor">Save & see my hut →</button>`);$('card').querySelectorAll('[data-style]').forEach(b=>b.onclick=()=>{progress[b.dataset.style]=b.dataset.value;save();applyHut();custom.refreshHut();decorate()});$('finishDecor').onclick=()=>{close();if(area==='hut')enter('forest');toast('Your hut is ready — '+progress.roommate+' loves it!')}}
function wardInteract(){if(progress.savedSchool)return panel('THE SCHOOL WARD','The crystal shines again.','You saved Redcliff. Its pupils can keep learning under the protection of the forest. The mysterious stranger is still out there…');if(!progress.authorized)return panel('A FLICKERING CRYSTAL','The ward is weakening.',progress.clues.length<3?'Someone has tampered with its base. Find the three clues and tell Headmistress Rowan.':'Complete all three lessons, then take your evidence to Headmistress Rowan. She will give you the restoration charm.');progress.savedSchool=true;save();updateQuest();crystal.material=mat('#b8ebbc');panel('CHAPTER ONE COMPLETE','You saved Redcliff!','You balance the crystal rings, restore their living energy, and speak the words of friendship. The ward flares into light. Your classmates cheer. In the distance, a grey-coated figure disappears between the trees, leaving one silver feather behind. Their identity remains a mystery…',[{title:'Return to school life',sub:'Keep learning, explore, and decorate with your classmates',fn:close}])}
function chapterOneJournal(){panel('SIERRA’S JOURNAL','The secret of Redcliff',progress.savedSchool?'The school is protected. An unknown member of the Ashwing Circle fled into the forest. A silver feather is our only lead.':progress.met?'Someone is trying to destroy the school by sabotaging its protective ward. Find evidence, learn how the ward works, then help Rowan protect everyone.':'A new term at a school hidden in the forest. Headmistress Rowan is waiting inside.',[{title:`Evidence · ${progress.clues.length}/3`,sub:progress.clues.map(id=>clueTexts[id][0]).join(' · ')||'No clues yet',fn:()=>panel('EVIDENCE','What we know',progress.clues.map(id=>'<b>'+clueTexts[id][0]+'</b><br>'+clueTexts[id][1]).join('<br><br>')||'Talk to Rowan, then investigate the forest and school.')},{title:`Learning · ${progress.lessons.length}/3 badges`,sub:progress.lessons.join(' · ')||'Maths · Forest Science · Languages',fn:()=>panel('YOUR SUBJECTS','Knowledge is your power.','Walk to a desk inside school to study Mathematics, Forest Science, or Languages. Finish all three questions in each subject to earn its badge.')},{title:'Where should I go?',sub:'School north · huts west · satchel east',fn:()=>panel('FOREST GUIDE','Follow the paths.','The school is north along the main path. The class huts are west along the side path. Theo and the lost satchel are east of the central clearing. The minimap shows you in white, school in gold, huts in brown, and satchel in purple. Inside school: Rowan is at the back, the archive to the right, and the torn note to the left.')}])}
function help(){panel('HOW TO PLAY','Your forest. Your adventure.','Hold the arrow buttons to walk. On a keyboard, use WASD or arrow keys. Tap Interact (E) near a door, classmate, desk, or clue. Use ↶ / ↷ (Q / R) to rotate the camera. Human opens doors; your ground animal runs faster; your bird can fly when you tap Flap (Space).',[{title:'About this adventure',sub:'A single-player 3D story with local saves',fn:()=>panel('ABOUT','Welcome to Redcliff.','Explore the forest and school, design your shared hut, and investigate two mysteries. Open Notebook for the Silent Stream chapter, four subject levels, evidence, notes and practice. Find its field station southeast of the school path. Progress saves on this browser. Classmates are game characters.')}])}
function interact(){if(modalOpen||!started)return;if(nearest)nearest.fn();else toast('Walk closer to a person, door, desk, or clue. Follow the path north to school.')}
function doJump(){if(stable?.riding)return;if(recreation?.mode){if(recreation.swimming)toast('Use arrows / WASD to swim, or Leave pool to get out.');return}if(area==='drive')return;if(modalOpen||!started)return;if(resting)standUp();if(form==='bird')vy=6;else if(jump<.01)vy=6}
function clearHeld(){held.clear()}document.querySelectorAll('[data-move]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);held.add(b.dataset.move)};const end=()=>held.delete(b.dataset.move);b.onpointerup=end;b.onpointercancel=end;b.onlostpointercapture=end});document.querySelectorAll('[data-form]').forEach(b=>b.onclick=()=>{if(!modalOpen)setForm(b.dataset.form)});$('interactBtn').onclick=interact;$('jumpBtn').onclick=doJump;$('journalBtn').onclick=()=>learning.notebook();$('helpBtn').onclick=help;$('camLeft').onclick=()=>yaw-=Math.PI/4;$('camRight').onclick=()=>yaw+=Math.PI/4;
const keyMap={KeyW:'forward',ArrowUp:'forward',KeyS:'back',ArrowDown:'back',KeyA:'left',ArrowLeft:'left',KeyD:'right',ArrowRight:'right'};window.addEventListener('keydown',e=>{if(modalOpen){if(e.code==='Escape'&&started)close();if(e.code==='Tab'){const fs=[...$('card').querySelectorAll('button:not(:disabled), select, textarea, input, a[href]')];if(fs.length&&(e.shiftKey&&document.activeElement===fs[0]||!e.shiftKey&&document.activeElement===fs.at(-1))){e.preventDefault();(e.shiftKey?fs.at(-1):fs[0]).focus()}}return}if(keyMap[e.code]||['Space','KeyE'].includes(e.code))e.preventDefault();if(keyMap[e.code])held.add(keyMap[e.code]);if(e.repeat)return;if(e.code==='KeyE')interact();if(e.code==='Space')doJump();if(e.code==='Digit1')setForm('human');if(e.code==='Digit2')setForm('wolf');if(e.code==='Digit3')setForm('bird');if(e.code==='KeyQ')yaw-=Math.PI/4;if(e.code==='KeyR')yaw+=Math.PI/4});window.addEventListener('keyup',e=>{if(keyMap[e.code])held.delete(keyMap[e.code])});window.addEventListener('blur',clearHeld);document.addEventListener('visibilitychange',clearHeld);
function blocked(x,z){if(area==='treehouse')return treeHouse.blocked(x,z);if(area==='forest'&&recreation?.blocks(x,z))return true;if(area==='store')return cityTrip.store.blocked(x,z);if(area==='city')return cityTrip.blocked(x,z);if(area==='hut')return Math.abs(x)>13.5||Math.abs(z)>11.8||custom.hutLayout.blocked(x,z);if(area!=='forest')return Math.abs(x)>11.8||Math.abs(z)>11.3;if(Math.abs(x)>65||z< -48||z>55)return true;if(jump>5&&form==='bird')return false;return colliders.some(c=>Math.abs(x-c.x)<c.w/2+.35&&Math.abs(z-c.z)<c.d/2+.35)}
function update(dt){realModels.tick(modalOpen?0:dt);t+=dt;if(toastTime>0){toastTime-=dt;if(toastTime<=0)$('toast').style.opacity=0}if(started&&!modalOpen&&area!=='drive'&&!recreation?.locksMovement){let x=(held.has('right')?1:0)-(held.has('left')?1:0),z=(held.has('back')?1:0)-(held.has('forward')?1:0);if(x||z){standUp();const len=Math.hypot(x,z);x/=len;z/=len;const dx=x*Math.cos(yaw)+z*Math.sin(yaw),dz=-x*Math.sin(yaw)+z*Math.cos(yaw),speed=stable?.riding?6:recreation?.swimming?3:form==='wolf'?8:form==='bird'?7:5;const nx=pos.x+dx*speed*dt,nz=pos.z+dz*speed*dt;if(!blocked(nx,pos.z))pos.x=nx;if(!blocked(pos.x,nz))pos.z=nz;avatar.rotation.y=Math.atan2(-dx,-dz);if(!stable?.riding&&!recreation?.swimming){for(const [i,sign] of [[3,1],[6,-1],[4,-1],[7,1]])humanBody.children[i].rotation.x=Math.sin(t*8)*.25*sign}humanBody.rotation.z=Math.sin(t*8)*.018;wolfBody.position.y=Math.abs(Math.sin(t*13))*.06}else{humanBody.rotation.z=0;if(!resting&&!stable?.riding&&!recreation?.mode)for(const i of [3,6,4,7])humanBody.children[i].rotation.x=0;}vy-=(form==='bird'?7:18)*dt;jump+=vy*dt;if(jump<=0){jump=0;vy=0}if(jump>8){jump=8;vy=Math.min(vy,0)}}if(resting&&!['bed','hammock'].includes(restKind))humanBody.children[7].rotation.x=-.35+Math.sin(t*1.5)*.2;custom.tick(dt);if(started&&!modalOpen)custom.hutLayout.tick(dt);if(started&&!modalOpen){recreation.tick(dt);treeHouse.tick(dt);stable?.tick(dt)}avatar.visible=area!=='drive';if(started&&!modalOpen)cityTrip.tick(dt);if(started&&!modalOpen)schoolLife.tick(dt);avatar.position.set(pos.x,jump+(recreation.mode&&recreation.mode!=='swim'?pos.y:0),pos.z);for(const [i,leg] of (wolfBody.userData.legs||[]).entries())leg.rotation.x=held.size&&!modalOpen?Math.sin(t*10+(i===0||i===3?0:Math.PI))*.35:0;wingL.rotation.z=Math.sin(t*12)*.4;wingR.rotation.z=-Math.sin(t*12)*.4;crystal.rotation.y=t*.4;crystal.position.y=1.7+Math.sin(t*2)*.1;if(progress.savedSchool)crystal.material=mat('#b8ebbc');const distance=area==='forest'?12:10.5;const desired=new THREE.Vector3(pos.x+Math.sin(yaw)*distance,8.5+jump*.6,pos.z+Math.cos(yaw)*distance);camera.position.lerp(desired,1-Math.exp(-dt*5));camera.lookAt(pos.x,1+jump*.5,pos.z-1);dayNight.tick(dt);village?.sync(progress.worldMinutes??540);nearest=null;let min=Infinity;for(const o of(area==='otherhut'?village.targets:area==='treehouse'?treeHouse.targets:area==='store'?cityTrip.store.targets:area==='city'?cityTrip.targets:area==='drive'?[]:area==='forest'?outTargets:area==='school'?schoolTargets:area==='classroom'?classTargets:hutTargets)){const d=Math.hypot(pos.x-o.x,pos.z-o.z);if(o.enabled!==false&&d<o.r&&d<min&&(o.aerial?form==='bird'&&jump>=4:jump<3)){nearest=o;min=d}}$('prompt').textContent=modalOpen?'':nearest?'✦ '+nearest.title+' · tap Interact':area==='drive'?'↑ Accelerate · ↓ Brake · ← → Steer':area==='city'?'Walk the sidewalks · café ahead · car at south end':area==='forest'?'↑ School · ← Huts · → Playground & pool':'';drawMap()}
const mq=$('map').getContext('2d');function drawMap(){if(area==='city'||area==='drive'){mq.fillStyle='#d4d4bb';mq.fillRect(0,0,160,160);mq.fillStyle='#59636a';mq.fillRect(71,0,18,160);if(area==='city')for(const z of [-20,0,20])mq.fillRect(0,80+z*1.7,160,12);mq.fillStyle='#fffbe9';mq.beginPath();mq.arc(80+pos.x*1.7,area==='drive'?Math.max(10,Math.min(150,145-(40-pos.z))):80+pos.z*1.7,4,0,7);mq.fill();return}mq.clearRect(0,0,160,160);mq.fillStyle=area==='forest'?'#93b27e':'#d4c49c';mq.fillRect(0,0,160,160);if(area==='forest'){mq.strokeStyle='#d9c89a';mq.lineWidth=6;mq.beginPath();mq.moveTo(80,20);mq.lineTo(80,145);mq.moveTo(80,101);mq.lineTo(30,101);mq.stroke();mq.fillStyle='#eccc7c';mq.fillRect(61,18,38,16);mq.fillStyle='#9b7659';mq.fillRect(28,84,12,10);mq.fillRect(21,109,10,8);mq.fillStyle='#c7b28c';mq.fillRect(126,64,30,28);mq.fillStyle='#69bbc9';mq.fillRect(125,109,34,21);mq.fillStyle='#d8bc83';mq.fillRect(54,113,18,15);mq.fillStyle='#527f9d';mq.fillRect(106,106,5,29);mq.fillStyle='#665479';mq.beginPath();mq.arc(113,94,3,0,7);mq.fill();mq.fillStyle='#fffbea';mq.beginPath();mq.arc(80+pos.x*1.7,82+pos.z*1.7,4,0,7);mq.fill();mq.strokeStyle='#38583d';mq.lineWidth=1;mq.stroke();mq.fillStyle='#365539';mq.font='bold 10px system-ui';mq.fillText('N',76,12)}else{mq.fillStyle='#6b8f6c';mq.font='bold 12px system-ui';mq.textAlign='center';mq.fillText(area==='otherhut'?'FRIENDS’ HUT':area==='treehouse'?'TREE HOUSE':area==='store'?'GROCERY':area==='school'?'SCHOOL':area==='classroom'?(schoolLife.subject==='Cafeteria'?'CAFETERIA':'CLASSROOM'):'YOUR HUT',80,32);mq.fillStyle='#fffbea';mq.beginPath();mq.arc(80+pos.x*4,80+pos.z*4,4,0,7);mq.fill();mq.fillStyle='#55725d';mq.fillText('EXIT ↓',80,145);mq.textAlign='left'}}
