const menuButton=$('menuBtn'),gameOptions=$('gameOptions');
function closeGameOptions(focus=false){gameOptions.hidden=true;menuButton.setAttribute('aria-expanded','false');if(focus)menuButton.focus()}
menuButton.onclick=()=>{const opening=gameOptions.hidden;gameOptions.hidden=!opening;menuButton.setAttribute('aria-expanded',String(opening));held.clear();if(opening)gameOptions.querySelector('button').focus()};
gameOptions.addEventListener('click',event=>{if(event.target.closest('button'))closeGameOptions(true)},{capture:true});
document.addEventListener('pointerdown',event=>{if(!gameOptions.hidden&&!event.target.closest('.tools'))closeGameOptions()});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!gameOptions.hidden){event.preventDefault();event.stopImmediatePropagation();closeGameOptions(true)}},{capture:true});
layoutHud();updateQuest();$('loading').hidden=true;panel('THE SECRET OF REDCLIFF','Welcome, Windwalker.','You are a Windwalker, a student who can shift into a ground animal and a bird. A forest school, new friends, and a hut to make your own await. Investigate the school mystery, or open Notebook to start The Silent Stream: science, mathematics, Latin and French. Choose a level for each subject.',[{title:'Choose my avatar & animals',sub:'Hair · clothes · ground animal · bird',fn:()=>custom.creator(true)},{title:'Enter the forest →',sub:'Explore · learn · decorate · uncover the mystery',fn:()=>{started=true;close();toast('Hold ↑ to follow the path to school. Tap Interact near the doors.')}}]);$('closeDialog').hidden=true;requestAnimationFrame(loop);
